describe("@sendfn/admin", () => {
  it("declares the inventoried operator surface and mutation policy", () => {
    expect(sendFnAdminCapability.schemaVersion).toBe("1.0");
    expect(sendFnAdminCapability.availability).toBe("required-product");
    expect(sendFnAdminCapability.scopeLevels).toEqual([
      "organization",
      "workspace",
      "project",
      "environment",
    ]);
    expect(
      sendFnAdminCapability.operations.some(
        (operation) => operation.id === "sendfn.providers.list",
      ),
    ).toBe(true);
    const mutation = sendFnAdminCapability.operations.find(
      (operation) => operation.safety.classification !== "read",
    );
    expect(mutation).toMatchObject({
      safety: {
        audit: "required",
        idempotent: true,
      },
    });
  });

  it("delegates the operation and complete scope to the injected domain service", async () => {
    const execute = vi.fn(async (request: SendFnAdminServiceRequest) => ({
      ok: true as const,
      data: {
        operationId: request.operationId,
        namespace: request.context.scope.namespace,
        region: request.context.scope.region,
      },
    }));
    const service: SendFnAdminService = { execute };
    const adapter = createSendFnAdminAdapter(service);

    const result = await adapter.execute(
      "sendfn.providers.list",
      { limit: 25 },
      context,
    );

    expect(result.data).toEqual({
      operationId: "sendfn.providers.list",
      namespace: "tenant_1",
      region: "in-south",
    });
    expect(execute).toHaveBeenCalledWith({
      operationId: "sendfn.providers.list",
      input: { limit: 25 },
      context,
    });
  });
});
