import type { AdminOperationError } from "./types.js";

export type AdminErrorCode =
  | "invalid_argument"
  | "unauthenticated"
  | "forbidden"
  | "not_found"
  | "conflict"
  | "rate_limited"
  | "precondition_failed"
  | "dependency_unavailable"
  | "internal";

const STATUS_BY_CODE: Record<AdminErrorCode, number> = {
  invalid_argument: 400,
  unauthenticated: 401,
  forbidden: 403,
  not_found: 404,
  conflict: 409,
  precondition_failed: 412,
  rate_limited: 429,
  dependency_unavailable: 503,
  internal: 500,
};

export class AdminError extends Error {
  readonly code: AdminErrorCode;
  readonly status: number;
  readonly details?: unknown;
  readonly retryable: boolean;

  constructor(
    code: AdminErrorCode,
    message: string,
    options: { status?: number; details?: unknown; retryable?: boolean; cause?: unknown } = {},
  ) {
    super(message, { cause: options.cause });
    this.name = "AdminError";
    this.code = code;
    this.status = options.status ?? STATUS_BY_CODE[code];
    this.details = options.details;
    this.retryable = options.retryable ?? (code === "rate_limited" || code === "dependency_unavailable");
  }
}

export function normalizeAdminError(
  error: unknown,
  identity: { requestId?: string; correlationId?: string } = {},
): AdminOperationError {
  const normalized = error instanceof AdminError
    ? error
    : new AdminError("internal", "The administration operation could not be completed.", { cause: error });
  return {
    ok: false,
    error: {
      code: normalized.code,
      message: normalized.message,
      status: normalized.status,
      ...(normalized.details === undefined ? {} : { details: normalized.details }),
      retryable: normalized.retryable,
    },
    ...identity,
  };
}
import { AdminError } from "./errors.js";
import { stableSerialize } from "./validator.js";
import type { AdminScope } from "./types.js";

export interface AdminCursorPayload<T = unknown> {
  version: 1;
  scope: AdminScope;
  position: T;
}

function toBase64Url(value: string): string {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function fromBase64Url(value: string): string {
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(value.length / 4) * 4, "=");
  const binary = atob(normalized);
  return new TextDecoder().decode(Uint8Array.from(binary, (character) => character.charCodeAt(0)));
}

export function encodeAdminCursor<T>(scope: AdminScope, position: T): string {
  return toBase64Url(JSON.stringify({ version: 1, scope, position } satisfies AdminCursorPayload<T>));
}

/**
 * Decodes the legacy encoded cursor after enforcing the embedded scope. This
 * helper does not authenticate cursor integrity: production domain providers
 * must issue opaque, signed cursor positions before exposing them.
 */
export function decodeAdminCursor<T>(cursor: string, expectedScope: AdminScope): T {
  try {
    const payload = JSON.parse(fromBase64Url(cursor)) as AdminCursorPayload<T>;
    if (payload.version !== 1 || stableSerialize(payload.scope) !== stableSerialize(expectedScope)) {
      throw new Error("scope mismatch");
    }
    return payload.position;
  } catch (error) {
    throw new AdminError("invalid_argument", "The pagination cursor is invalid for the active scope.", { cause: error });
  }
}

export function normalizeAdminPageLimit(
  value: unknown,
  options: { defaultLimit?: number; maxLimit?: number } = {},
): number {
  const defaultLimit = options.defaultLimit ?? 50;
  const maxLimit = options.maxLimit ?? 200;
  const limit = value === undefined ? defaultLimit : Number(value);
  if (!Number.isInteger(limit) || limit < 1 || limit > maxLimit) {
    throw new AdminError("invalid_argument", `Page limit must be an integer between 1 and ${maxLimit}.`);
  }
  return limit;
}
import type { AdminCapabilityManifest } from "./types.js";

/** Defines a capability while preserving literal operation identifiers for consumers. */
export function defineAdminCapability<const TManifest extends AdminCapabilityManifest>(
  manifest: TManifest,
): TManifest {
  return manifest;
}

