function isImplicitSecretKey(key: string): boolean {
  const normalized = key.replace(/[-_\s]/g, "").toLowerCase();
  if (
    /(?:password|passwd|secret|token|authorization|cookie|credential|privatekey|apikey)/.test(
      normalized,
    )
  ) {
    return true;
  }
  return [
    "code",
    "otp",
    "otpcode",
    "recoverycode",
    "recoverycodes",
    "session",
    "sessionid",
    "verificationcode",
  ].includes(normalized);
}

